/* @author MILO-GAO(高振銘)@2020 */ package page2020.unit;import java.util.ArrayList;import java.util.List;import page2020.core.Name;public class Func extends Name<Func> {	private String sysCode;	private String icon;	private String code;	private String subCode;	private String action;	private List<String> buttons = new ArrayList<String>();	private String menu;	@Override	public Func copy() {		Func bean = super.copy();		bean.setButtons(new ArrayList<String>(this.buttons));		return bean;	}	@Override	public String toString() {		return "Func [sysCode=" + sysCode + ", icon=" + icon + ", code=" + code + ", subCode=" + subCode + ", action="				+ action + ", buttons=" + buttons + ", menu=" + menu + "]";	}	public String getSysCode() {		return sysCode;	}	public void setSysCode(String sysCode) {		this.sysCode = sysCode;	}	public String getIcon() {		return icon;	}	public void setIcon(String icon) {		this.icon = icon;	}	public String getCode() {		return code;	}	public void setCode(String code) {		this.code = code;	}	public String getSubCode() {		return subCode;	}	public void setSubCode(String subCode) {		this.subCode = subCode;	}	public String getAction() {		return action;	}	public void setAction(String action) {		this.action = action;	}		public List<String> getButtons() {		return buttons;	}	public void setButtons(List<String> buttons) {		this.buttons = buttons;	}	public String getMenu() {		return menu;	}	public void setMenu(String menu) {		this.menu = menu;	}}